def rows_native(raw):
    result=collections.defaultdict(list)
    # Admite las dos variantes de espaciado documentadas: "11839 . a . 9600" y "00014. . t . . 1000".
    pat=re.compile(r'^\s*(\d{5})\s*\.\s*(?:\.\s*)?([act])\s*\.\s*(?:\.\s*)?(\d{3,7})\s*$',re.I)
    for page,part in enumerate(raw.split('\f'),1):
        for line in part.splitlines():
            m=pat.match(line)
            if m:
                result[(m.group(1),m.group(2).lower())].append({'pagina':page,'texto':line.strip(),'euros_decimo':int(m.group(3))/10})
    return result

def main():
    ref=json.loads(zlib.decompress(base64.b85decode(DATA)).decode())
    dest=pathlib.Path('salida_111');dest.mkdir(exist_ok=True)
    summary={'version':'1.11','fecha_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'motor_validado':False,'publicable':False,'historico_modificado':False,'anios':{},'advertencia':'No confundir coincidencia por regla con una fila literalmente encontrada en el PDF. El texto extraido del PDF termina antes del 99999 en ambos anios.'}
    for year in (2024,2025):
        raw=ref[f'pdf_text_{year}']; rows=rows_native(raw)
        prev={x['numero']:x for x in ref[f'premios_{year}']}
        major=ref[f'mayores_{year}']['premios']; gordo=next(p['numero'] for p in major if p['categoria']=='primerPremio')
        # Terminaciones de 2 cifras de los tres primeros premios, explicitadas por las filas t del PDF.
        terminaciones=sorted({p['numero'][-2:] for p in major if p['categoria'] in ('primerPremio','segundoPremio','tercerPremio')})
        findings=[]; counts=collections.Counter(); issues=[]
        for n in range(100000):
            num=f'{n:05d}'; comps=prev.get(num,{}).get('componentes_adicionales',[])
            for marker,category in [('a','aproximacion'),('t','terminacion')]:
                motor=sorted(int(round(c['euros_decimo']*100)) for c in comps if c['categoria']==category)
                literal=rows.get((num,marker),[])
                pdf=sorted(int(round(x['euros_decimo']*100)) for x in literal)
                if motor==pdf:
                    if motor:counts[f'{category}_literal_coincidente']+=1
                    continue
                if category=='terminacion' and motor==[10000] and not literal and num[-2:] in terminaciones and num not in [p['numero'] for p in major if p['categoria'] in ('primerPremio','segundoPremio','tercerPremio')]:
                    kind='inferido_por_regla_sin_fila_pdf';counts['terminacion_inferida_sin_fila']+=1
                else:
                    kind='discrepancia_sin_resolver';counts[f'{category}_sin_resolver']+=1
                record={'numero':num,'categoria':category,'clasificacion':kind,'motor_centimos':motor,'pdf_centimos':pdf,'evidencia_literal':literal,'terminaciones_referencia':terminaciones if category=='terminacion' else None}
                findings.append(record)
                if kind=='discrepancia_sin_resolver':issues.append(record)
        report={'anio':year,'sha256_pdf_texto':hashlib.sha256(raw.encode()).hexdigest(),'sha256_pdf_documento_referencia':ref[f'pdf_sha_{year}'],'terminaciones_dos_cifras':terminaciones,'conteos':dict(counts),'hallazgos':findings,'discrepancias_no_resueltas':issues,'estado':'VALIDACION_PARCIAL','motor_validado':False,'publicable':False,'limitaciones':['Las filas ausentes no se convierten en evidencia literal por deduccion','El PDF contiene un texto de nota de terminaciones, pero su extraccion esta degradada','Se necesita contrastar los registros no presentes en la lectura con otra fuente independiente o inspeccion visual']}
        (dest/f'auditoria_terminaciones_aproximaciones_{year}_111.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
        summary['anios'][str(year)]={'conteos':dict(counts),'hallazgos':len(findings),'discrepancias_no_resueltas':len(issues)}
    (dest/'informe_navidad_111.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps(summary,ensure_ascii=False,indent=2))
if __name__=='__main__':main()
